insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_90_v1'
from (values
('127.697.d.1.A',3,'A GIS student opens mapping software, saves a file in a folder and emails the map to a classmate. These tasks use:','["operating systems, applications and networking tools together", "only a calculator", "only a printer", "no software at all"]'::jsonb,0,'GIS work blends OS, application and network skills.','original'),
('127.697.d.1.A',4,'Before sharing a large map file with a team, a GIS technician should confirm that:','["the file has no name", "the recipients can open the file with their software and network access", "the file is deleted afterward", "the screen is dimmed"]'::jsonb,1,'Tools must work for every user.','original'),
('127.697.d.1.B',3,'In a GIS workstation, a digitizing tablet or scanner is an example of a(n):','["output device", "storage battery", "input device", "network cable"]'::jsonb,2,'Tablets and scanners bring data in.','original'),
('127.697.d.1.B',4,'A plotter that prints a large map is best described as a(n):','["processing chip", "input device", "memory slot", "output device"]'::jsonb,3,'Plotters produce printed output.','original'),
('127.697.d.1.C',3,'A team picks a mapping program by checking whether it can do the needed analysis, fits the budget and is reliable. They are:','["evaluating software quality and appropriateness", "painting maps", "deleting files", "naming layers"]'::jsonb,0,'Software is chosen against project needs.','original'),
('127.697.d.1.C',4,'Which factor matters most when selecting GIS software for a county water project?','["The number of icons on the desktop", "Whether it can handle the needed spatial data and analysis", "The name of the company founder", "The color of the box"]'::jsonb,1,'Capability for the task comes first.','original'),
('127.697.d.1.D',3,'A map layer saved in one format will not open in a second program. The technician should:','["retype every point by hand", "delete the layer", "convert the file to a compatible format", "buy a new monitor"]'::jsonb,2,'Format conversion solves compatibility issues.','original'),
('127.697.d.1.D',4,'A shapefile works on a Windows laptop but a coworker on another platform cannot open it. The first thing to check is:','["screen resolution", "keyboard layout", "desk size", "cross-platform format and software compatibility"]'::jsonb,3,'Compatibility issues are about formats and software.','original'),
('127.697.d.2.A',3,'A student uses a digital camera, a scanner and a GPS receiver to collect map data. These are:','["input devices", "storage racks", "display stands", "output devices only"]'::jsonb,0,'They bring data into the project.','original'),
('127.697.d.2.A',4,'Adding a GPS-tagged photo to a map product shows the use of:','["a printer jam", "an input device feeding a final product", "a lost password", "a power outage"]'::jsonb,1,'Inputs are incorporated into products.','original'),
('127.697.d.2.B',3,'Using the correct finger placement on home-row keys follows:','["a coordinate grid", "a map legend", "keyboarding standards", "a license"]'::jsonb,2,'Proper technique supports accurate data entry.','original'),
('127.697.d.2.B',4,'Accurate data entry matters in GIS because a mistyped coordinate can:','["improve the map", "change the legend font", "speed up the printer", "place a feature in the wrong location"]'::jsonb,3,'Small typos create large location errors.','original'),
('127.697.d.3.A',3,'Early thematic mapping, such as John Snow''s cholera map, is an example of:','["a historical use of mapping to find patterns", "a GPS satellite", "a smartphone app", "a drone camera"]'::jsonb,0,'Mapped data revealed patterns in the past.','original'),
('127.697.d.3.A',4,'A contemporary development that makes GIS data easy to share is:','["hand-drawn charts", "web-based mapping platforms", "typewriters", "paper-only atlases"]'::jsonb,1,'Web mapping expanded access.','original'),
('127.697.d.3.B',3,'Which is a basic component of a GIS?','["pens, rulers and chalk", "chairs, desks and shelves", "hardware, software and data", "paint, glue and string"]'::jsonb,2,'GIS rests on hardware, software, data and people.','original'),
('127.697.d.3.B',4,'In a GIS, the people component includes:','["only the keyboard", "only the map paper", "only the monitor", "analysts who manage, run and interpret the system"]'::jsonb,3,'People operate and apply the GIS.','original'),
('127.697.d.3.C',3,'A city planner uses GIS to decide where to put a new fire station. This shows GIS used in:','["public safety and planning careers", "music production", "bakery sales", "fashion design"]'::jsonb,0,'GIS supports location decisions.','original'),
('127.697.d.3.C',4,'A farmer uses GIS and soil maps to adjust fertilizer across fields. This is an example of GIS in:','["banking only", "agriculture", "film editing", "retail clothing"]'::jsonb,1,'Precision agriculture relies on spatial data.','original'),
('127.697.d.4.A',3,'In a relational database built from a geographic data model, each map feature is linked to:','["a color wheel", "a coin", "a table row of attributes", "a paper file"]'::jsonb,2,'Attributes are stored in tables.','original'),
('127.697.d.4.A',4,'A geographic data model for roads might include attributes such as:','["lunch menu", "paint color of the sky", "student grades", "name, length and speed limit"]'::jsonb,3,'Attributes describe features.','original'),
('127.697.d.4.B',3,'A join in a database combines two tables using:','["a field they share", "the screen size", "the printer name", "a random number"]'::jsonb,0,'Joins match records on a common field.','original'),
('127.697.d.4.B',4,'Clicking a hyperlink field on a map feature to open its inspection report shows the use of:','["a battery drain", "hyperlinks within a database", "a projection", "a sorting error"]'::jsonb,1,'Hyperlinks connect features to related documents.','original'),
('127.697.d.4.C',3,'Grouping population values into ranges such as low, medium and high for a map is called:','["scaling a font", "encryption", "classification", "deletion"]'::jsonb,2,'Classification groups data into classes.','original'),
('127.697.d.4.C',4,'A mapmaker splits rainfall data into five classes with equal value ranges. This is the:','["random method", "alphabet method", "backup method", "equal interval classification method"]'::jsonb,3,'Equal interval uses same-width ranges.','original'),
('127.697.d.4.D',3,'Importing a spreadsheet of addresses into a GIS database is an example of:','["transferring data from another source into a database", "changing a legend", "printing a map", "erasing a layer"]'::jsonb,0,'Data can be imported from many sources.','original'),
('127.697.d.4.D',4,'Before importing a spreadsheet into a GIS database, a technician should:','["rename the file to a number only", "check that columns and data types match what the database expects", "delete all headers", "turn off the computer"]'::jsonb,1,'Clean, matching data imports correctly.','original'),
('127.697.d.5.A',3,'A satellite image downloaded from a government site is an example of a:','["music file", "recipe card", "spatial data source", "phone bill"]'::jsonb,2,'Imagery is a common spatial source.','original'),
('127.697.d.5.A',4,'Which source is a digital spatial database commonly used in GIS?','["A weather vane", "A grocery receipt", "A school lunch menu", "A county''s online parcel and road layers"]'::jsonb,3,'Public agencies publish spatial layers.','original'),
('127.697.d.5.B',3,'Using GIS to find all schools within one mile of a highway is an example of:','["spatial analysis", "slide design", "file renaming", "word processing"]'::jsonb,0,'Spatial analysis answers location questions.','original'),
('127.697.d.5.B',4,'Spatial analysis is used appropriately when a planner wants to:','["sort an email inbox", "identify where a flood zone overlaps with homes", "spell check a letter", "edit a video"]'::jsonb,1,'Overlay analysis reveals relationships between locations.','original'),
('127.697.d.6.A',3,'A GIS technician needs to measure the distance between two points on a map. They should choose the:','["print preview", "font menu", "measurement tool", "spell checker"]'::jsonb,2,'Pick the tool that does the task.','original'),
('127.697.d.6.A',4,'For combining a flood layer with a parcel layer to find affected lots, the best tool is:','["a screen saver", "a color picker", "a text box", "an overlay tool"]'::jsonb,3,'Overlay tools combine layers.','original'),
('127.697.d.6.B',3,'A query that selects all parcels larger than five acres is an example of:','["an attribute query", "a printing job", "a font change", "a battery check"]'::jsonb,0,'Attribute queries select by data values.','original'),
('127.697.d.6.B',4,'A spatial query that finds all features within a boundary uses the:','["alphabet order of names", "location relationship between features and the boundary", "screen brightness", "file size"]'::jsonb,1,'Spatial queries use position and shape.','original'),
('127.697.d.6.C',3,'Mapmakers use a map projection when they need to:','["print only text", "change file names", "show the curved Earth on a flat surface", "delete data"]'::jsonb,2,'Projections flatten the globe.','original'),
('127.697.d.6.C',4,'Every map projection distorts something, so a mapmaker chooses one that:','["makes the map blurry", "hides the legend", "removes all labels", "preserves the property most important to the map''s purpose"]'::jsonb,3,'Different projections preserve shape, area or distance.','original'),
('127.697.d.6.D',3,'Latitude and longitude are used to describe:','["a location''s coordinates on Earth", "a paint color", "a printer setting", "a file size"]'::jsonb,0,'Coordinates pinpoint places.','original'),
('127.697.d.6.D',4,'A map scale of 1:24,000 means one unit on the map equals:','["240 units on the ground", "24,000 of the same units on the ground", "24 units on the ground", "1,000 units on the ground"]'::jsonb,1,'Scale ratios compare map to ground distance.','original'),
('127.697.d.7.A',3,'Before a class GPS data collection trip, a supervisor should:','["skip all instructions", "leave without a plan", "plan the route, safety rules and tasks", "bring no equipment"]'::jsonb,2,'Supervised experiences are planned.','original'),
('127.697.d.7.A',4,'A safe GPS field experience for students includes:','["entering restricted areas", "ignoring weather", "working alone at night", "adult supervision and a clear plan for the area"]'::jsonb,3,'Safety and supervision come first.','original'),
('127.697.d.7.B',3,'Before collecting points, a GPS receiver should be:','["turned on and given time to lock onto satellites", "held upside down in a closed box", "covered in a bag", "turned off"]'::jsonb,0,'Receivers need a satellite fix.','original'),
('127.697.d.7.B',4,'A technician sets the receiver''s coordinate system and data format before collecting. This step is part of:','["deleting waypoints", "initializing and preparing the receiver", "printing the map", "closing the project"]'::jsonb,1,'Settings must match the project.','original'),
('127.697.d.7.C',3,'A GPS receiver records a location as:','["a song", "a recipe", "coordinates such as latitude and longitude", "a paragraph"]'::jsonb,2,'GPS reports coordinates.','original'),
('127.697.d.7.C',4,'To get the best accuracy when collecting a point, the user should:','["stand under a thick roof", "move quickly while recording", "cover the antenna", "hold still in an open area with a clear view of the sky"]'::jsonb,3,'Clear sky view improves the fix.','original'),
('127.697.d.7.D',3,'After the field work, the saved points on the GPS unit are:','["downloaded to a personal computer", "thrown away", "spoken aloud", "painted on paper"]'::jsonb,0,'Data is transferred for processing.','original'),
('127.697.d.7.D',4,'A common way to move GPS data to a computer is with:','["a rubber band", "a USB cable or wireless transfer and the manufacturer''s software", "a pencil", "a fax"]'::jsonb,1,'Standard tools transfer the files.','original'),
('127.697.d.8.A',3,'A student collects text notes, photos, audio and video clips for a GIS project. This is:','["printing blank paper", "erasing layers", "gathering electronic information in various formats", "deleting files"]'::jsonb,2,'Multiple formats enrich a project.','original'),
('127.697.d.8.A',4,'When collecting electronic information for a GIS project, it is best to:','["rename everything with one letter", "use only memory", "skip the source", "record the source and date of each item"]'::jsonb,3,'Documented sources support credibility.','original'),
('127.697.d.8.B',3,'Authentic data for a GIS project comes from:','["reliable electronic sources such as government agencies", "random rumors", "guesses", "unsigned posts with no source"]'::jsonb,0,'Authentic data is traceable and reliable.','original'),
('127.697.d.8.B',4,'Before using data from a website in a map, a student should check that it is:','["the most colorful", "from a credible source and up to date", "the longest page", "the first search result"]'::jsonb,1,'Credibility and currency matter.','original'),
('127.697.d.9.A',3,'Project management for a GIS project includes setting goals, tasks and:','["a random password", "a color theme only", "a timeline", "a lunch menu"]'::jsonb,2,'Management guidelines include planning.','original'),
('127.697.d.9.A',4,'A GIS project team lists tasks, assigns people and sets deadlines. This is:','["losing data", "skipping the plan", "ending the project", "applying project management guidelines"]'::jsonb,3,'Organization keeps projects on track.','original'),
('127.697.d.9.B',3,'A flowchart for a GIS project shows:','["the steps and decisions in the project in order", "only the map colors", "random notes", "only the final grade"]'::jsonb,0,'Visual organizers plan solutions.','original'),
('127.697.d.9.B',4,'A schematic used in a GIS project would best show:','["a seating chart", "how data flows between tools and layers", "a lunch order", "a poster''s border"]'::jsonb,1,'Schematics show relationships and flow.','original'),
('127.697.d.10.A',3,'A finished map can be published as a printed poster or as a:','["recipe", "calendar notice", "digital file such as a PDF or web map", "soundtrack"]'::jsonb,2,'Maps can be published in print or digital forms.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_90_v1'
from (values
('127.697.d.10.A',4,'When choosing a publication format for a map, the mapmaker should consider:','["the pen color only", "the weather only", "the file icon only", "the audience and how they will use the map"]'::jsonb,3,'Format follows audience and use.','original'),
('127.697.d.10.B',3,'A GIS presentation could include maps, charts and:','["graphs that support the findings", "unrelated photos", "only the title", "blank slides"]'::jsonb,0,'Visuals support the message.','original'),
('127.697.d.10.B',4,'In a GIS presentation to a city council, the mapmaker should:','["skip the data", "use clear maps and charts that support the main point", "hide the map", "fill slides with dense text only"]'::jsonb,1,'Clear visuals communicate findings.','original'),
('127.697.d.11.A',3,'A reader is confused by a map''s colored symbols. The part of the map that explains them is the legend, which tells:','["when school ends", "what is for lunch", "what the symbols and colors on the map mean", "who owns the printer"]'::jsonb,2,'Legends are keys to symbols.','original'),
('127.697.d.11.A',4,'Industry-standard legends help GIS users because they:','["delete symbols", "remove the scale", "hide the data", "let different people read maps the same way"]'::jsonb,3,'Standard legends promote consistent interpretation.','original'),
('127.697.d.11.B',3,'Which is a common map element?','["a scale bar", "a stapler", "a lunch tray", "a jump rope"]'::jsonb,0,'Scale bars, north arrows and titles are map elements.','original'),
('127.697.d.11.B',4,'A north arrow on a map tells the reader:','["the paper weight", "which direction is north", "the map''s price", "the printer brand"]'::jsonb,1,'It orients the map.','original'),
('127.697.d.11.C',3,'A GIS can summarize attribute data in a:','["song", "recipe", "report or graph", "lock"]'::jsonb,2,'Reports and graphs summarize data.','original'),
('127.697.d.11.C',4,'A GIS report that totals the acres of each land use type is:','["a map projection", "a GPS satellite", "a random list", "a summary generated from attribute data"]'::jsonb,3,'Reports summarize attributes.','original'),
('127.697.d.11.D',3,'A map that shades regions by the value of a variable, such as population density, is a:','["choropleth map", "weather vane", "paper airplane", "road atlas"]'::jsonb,0,'Choropleth maps use shading by value.','original'),
('127.697.d.11.D',4,'A heat map is best used to show:','["a file name", "where values or events are concentrated", "a legend only", "a single location only"]'::jsonb,1,'Heat maps highlight concentrations.','original'),
('127.698.d.1.A',3,'A student interested in mapping careers could find a job as a:','["stage actor", "fashion buyer", "GIS technician or analyst", "pastry chef"]'::jsonb,2,'GIS fields employ technicians and analysts.','original'),
('127.698.d.1.A',4,'Which job uses GIS to plan evacuation routes before storms?','["stage designer", "bakery cashier", "hair stylist", "emergency management planner"]'::jsonb,3,'Emergency planners rely on spatial data.','original'),
('127.698.d.1.B',3,'Spending a day observing a GIS analyst at work is a learning experience called:','["job shadowing", "a final exam", "a license test", "a group quiz"]'::jsonb,0,'Shadowing gives a look at real work.','original'),
('127.698.d.1.B',4,'A student gets school credit for working part-time at a county mapping office. This is a:','["pop quiz", "career preparation experience such as an internship", "summer break", "study hall"]'::jsonb,1,'Internships build career skills.','original'),
('127.698.d.1.C',3,'A certification in GIS shows an employer that a person has:','["a free computer", "a new job automatically", "verified skills and knowledge", "a driver''s license"]'::jsonb,2,'Industry certifications validate skills.','original'),
('127.698.d.1.C',4,'Industry certifications for GIS-related careers are earned by:','["writing a letter", "watching a movie", "buying a map", "passing an exam from a recognized organization"]'::jsonb,3,'Credentials are earned through assessment.','original'),
('127.698.d.1.D',3,'Using someone''s location data without permission raises an ethical issue about:','["privacy", "screen glare", "font size", "paper weight"]'::jsonb,0,'Location data can reveal personal details.','original'),
('127.698.d.1.D',4,'A GIS analyst should avoid sharing maps that show:','["a state boundary", "private home locations of vulnerable people without consent", "a public park", "a river''s name"]'::jsonb,1,'Ethics protect privacy and safety.','original'),
('127.698.d.2.A',3,'Why is teamwork important in a GIS project?','["It avoids all planning", "It hides errors", "Different members bring different skills and share the workload", "It removes the need for data"]'::jsonb,2,'Large projects need collaboration.','original'),
('127.698.d.2.A',4,'A GIS project needs a data collector, an analyst and a map designer. This shows the value of:','["working alone", "skipping tasks", "random assignments", "teamwork with specialized roles"]'::jsonb,3,'Roles combine to finish the work.','original'),
('127.698.d.2.B',3,'A teammate disagrees about which map colors to use. The best principle for handling it is:','["calm conflict resolution through discussion", "yelling", "quitting the team", "ignoring the teammate"]'::jsonb,0,'Effective teams resolve conflict respectfully.','original'),
('127.698.d.2.B',4,'Collaboration on a GIS team includes:','["hiding progress", "sharing ideas, listening and agreeing on goals", "working in secret", "blaming others"]'::jsonb,1,'Collaboration needs communication.','original'),
('127.698.d.2.C',3,'A strong team leader:','["ignores deadlines", "makes all decisions silently", "guides the group and values every member''s input", "avoids all work"]'::jsonb,2,'Good leaders support the team.','original'),
('127.698.d.2.C',4,'A strong team member:','["skips meetings", "blames others", "works only for themselves", "meets deadlines and supports teammates"]'::jsonb,3,'Reliability and support characterize strong members.','original'),
('127.698.d.3.A',3,'A camera lens collects and focuses light to form an image. In aerial photography, a longer focal length gives:','["a narrower, more magnified view", "a wider view", "no image", "a dim view only"]'::jsonb,0,'Focal length affects field of view.','original'),
('127.698.d.3.A',4,'The camera''s film or sensor in aerial photography records:','["the pilot''s voice", "the focused light from the ground scene", "the fuel level", "the engine temperature"]'::jsonb,1,'Sensors capture the image.','original'),
('127.698.d.3.B',3,'Early aerial photographs were taken from platforms such as:','["trucks", "submarines", "balloons, kites and pigeons", "bicycles"]'::jsonb,2,'Early platforms were simple aircraft and balloons.','original'),
('127.698.d.3.B',4,'Aerial photography developed rapidly in wartime because of its value for:','["cooking", "sports scoring", "music", "reconnaissance and mapping"]'::jsonb,3,'Military use pushed the technology forward.','original'),
('127.698.d.3.C',3,'A land developer uses aerial photos to:','["study a site before building", "write a song", "bake a cake", "paint a portrait"]'::jsonb,0,'Aerial photos show terrain and features.','original'),
('127.698.d.3.C',4,'Aerial photography is used by farmers to:','["dye fabric", "check crop health across fields", "tune pianos", "print recipes"]'::jsonb,1,'It reveals field conditions.','original'),
('127.698.d.3.D',3,'A photograph taken with the camera pointing straight down is a:','["panorama only", "oblique aerial photograph", "vertical aerial photograph", "portrait"]'::jsonb,2,'Vertical photos look straight down.','original'),
('127.698.d.3.D',4,'An oblique aerial photograph differs from a vertical one because it:','["is taken straight down", "has no horizon", "never shows buildings", "is taken at an angle, showing sides of objects"]'::jsonb,3,'Oblique views show angled perspective.','original'),
('127.698.d.3.E',3,'In an aerial photo, long straight dark lines connecting towns are most likely:','["roads", "shadows of the moon", "clouds", "rivers'' deltas"]'::jsonb,0,'Roads appear as straight linear features.','original'),
('127.698.d.3.E',4,'In an aerial photo, a long dark curved band bordering open water is likely a:','["parking lot", "shoreline", "airport runway", "highway overpass"]'::jsonb,1,'Shorelines mark land-water boundaries.','original'),
('127.698.d.4.A',3,'Electromagnetic radiation from the Sun travels through space as:','["liquid", "sound only", "waves of energy", "solid rock"]'::jsonb,2,'EM radiation propagates as waves.','original'),
('127.698.d.4.A',4,'When EM energy reaches Earth''s surface it can be reflected, absorbed or:','["printed", "spoken", "frozen", "transmitted"]'::jsonb,3,'Matter interacts with energy in these ways.','original'),
('127.698.d.4.B',3,'When light bends as it passes from air into water, the wave behavior is:','["refraction", "pixelation", "deletion", "scaling"]'::jsonb,0,'Refraction is bending at a boundary.','original'),
('127.698.d.4.B',4,'Light spreading in many directions after hitting small particles in the air is:','["printing", "scattering", "freezing", "focusing"]'::jsonb,1,'Scattering redirects waves.','original'),
('127.698.d.4.C',3,'According to thermal radiation laws, hotter objects emit:','["no energy", "only sound", "more energy at shorter wavelengths", "less energy than cold objects"]'::jsonb,2,'Hotter objects radiate more and at shorter wavelengths.','original'),
('127.698.d.4.C',4,'All objects above absolute zero emit thermal radiation, so a thermal sensor can detect:','["only sounds", "only smells", "only colors", "differences in surface temperature"]'::jsonb,3,'Thermal sensors read emitted heat.','original'),
('127.698.d.4.D',3,'The wave model of light explains behaviors such as:','["interference and diffraction", "paper folding", "batteries", "glue drying"]'::jsonb,0,'Wave behaviors include interference.','original'),
('127.698.d.4.D',4,'The particle model of light describes it as streams of:','["raindrops", "photons", "grains of sand", "atoms of water"]'::jsonb,1,'Photons are light particles.','original'),
('127.698.d.4.E',3,'A map made from reflected visible light shows how objects look. A thermal image map shows:','["only street names", "only sounds", "how hot or cold surfaces are", "only borders"]'::jsonb,2,'Thermal imagery maps temperature.','original'),
('127.698.d.4.E',4,'To tell which parts of a city lose the most heat at night, an analyst would use:','["a calendar", "a road atlas", "a recipe", "thermal radiation imagery"]'::jsonb,3,'Thermal images show heat loss.','original'),
('127.698.d.4.F',3,'To map wildfire hot spots through smoke, the better choice is:','["thermal imagery", "a street guide", "a paper map", "visible-light photos only"]'::jsonb,0,'Thermal sensors detect heat through smoke.','original'),
('127.698.d.4.F',4,'Choosing between visible and thermal imagery should be based on:','["the desk''s size", "what the project needs to detect", "the printer brand", "the file''s color"]'::jsonb,1,'Match sensor to purpose.','original'),
('127.698.d.5.A',3,'Passive microwave remote sensing measures:','["visible paint", "sound waves", "naturally emitted microwave energy", "its own transmitted pulses"]'::jsonb,2,'Passive systems detect natural energy.','original'),
('127.698.d.5.A',4,'Active microwave systems such as radar differ because they:','["record nothing", "only wait for the sun", "use no energy", "send out their own signal and measure the return"]'::jsonb,3,'Active sensors transmit pulses.','original'),
('127.698.d.5.B',3,'In radar imagery, a rough surface generally appears:','["brighter because it scatters more energy back", "darker always", "blue only", "invisible"]'::jsonb,0,'Roughness increases backscatter.','original'),
('127.698.d.5.B',4,'Wet soil usually returns a stronger radar signal than dry soil because of:','["its smell", "its higher moisture content", "its lower moisture", "its color"]'::jsonb,1,'Moisture changes the radar response.','original'),
('127.698.d.5.C',3,'An analyst studying a radar image of a coastline can often tell:','["the user''s password", "the day''s menu", "water from land by differences in brightness", "the owner''s name"]'::jsonb,2,'Smooth water and rough land differ in radar returns.','original'),
('127.698.d.5.C',4,'A detailed radar image analysis of a flood would compare:','["a single blank page", "only the title", "music playlists", "images before and after the event to find changes"]'::jsonb,3,'Change detection reveals flooding.','original'),
('127.698.d.6.A',3,'Raster-based GIS software stores data as:','["a grid of cells with values", "paper sheets", "only text", "only lines"]'::jsonb,0,'Rasters are cell grids.','original'),
('127.698.d.6.A',4,'Using raster software to compute the average elevation of cells within a watershed is an example of:','["word counting", "raster analysis", "font choosing", "file deleting"]'::jsonb,1,'Cell-based math is raster analysis.','original')
